function snare(at){hat(at,.16);const o=demoCtx.createOscillator(),g=demoCtx.createGain();o.type='triangle';o.frequency.setValueAtTime(190,at);o.frequency.exponentialRampToValueAtTime(90,at+.12);g.gain.setValueAtTime(.15,at);g.gain.exponentialRampToValueAtTime(.001,at+.14);o.connect(g);g.connect(demoCtx.destination);o.start(at);o.stop(at+.15)}
