function startDemoAudio(from=0){const AC=window.AudioContext||window.webkitAudioContext;if(!demoCtx)demoCtx=new AC();demoCtx.resume();demoOrigin=demoCtx.currentTime-from;let step=Math.max(0,Math.floor(from/(60/bpm/2)));function scheduler(){const now=currentTime(),stepDur=60/bpm/2;while(step*stepDur<now+.12){const t=demoCtx.currentTime+Math.max(0,step*stepDur-now);if(step%4===0)kick(t);if(step%8===4)snare(t);if(step%2===0)hat(t,.045);if(step%4===0)bass(t,step);step++}}clearInterval(demoTimer);demoTimer=setInterval(scheduler,25);scheduler()}
